import {Router,type Request} from 'express';
import type {PoolConnection,ResultSetHeader,RowDataPacket} from 'mysql2/promise';
import {query,transaction} from '../../config/database.js';
import {asyncHandler} from '../../middleware/error-handler.js';
import {requirePermission} from '../../middleware/require-permission.js';
import {HttpError} from '../../shared/http-error.js';
import {assertPermission,can,rbac,type PermissionScope} from '../rbac/rbac.service.js';

export const hrRouter=Router();
type Input=Record<string,unknown>;
const id=(v:unknown)=>{const x=String(v??'');if(!/^\d+$/.test(x)||x==='0')throw new HttpError(400,'Identifiant invalide.');return x};
const text=(v:unknown,label:string,required=false,max=190)=>{const x=typeof v==='string'?v.trim():'';if(required&&!x)throw new HttpError(400,`${label} obligatoire.`);if(x.length>max)throw new HttpError(400,`${label} trop long.`);return x||null};
const date=(v:unknown,label:string)=>{const x=String(v??'');if(!/^\d{4}-\d{2}-\d{2}$/.test(x)||Number.isNaN(Date.parse(`${x}T00:00:00Z`)))throw new HttpError(400,`${label} invalide.`);return x};
const positive=(v:unknown,label:string,scale=2)=>{const raw=String(v??'').trim();if(!/^\d+(?:\.\d+)?$/.test(raw))throw new HttpError(400,`${label} invalide.`);const n=Number(raw);if(!Number.isFinite(n)||n<=0)throw new HttpError(400,`${label} doit être supérieur à zéro.`);return n.toFixed(scale)};
const nonNegative=(v:unknown,label:string,scale=3)=>{const raw=String(v??'').trim();if(!/^\d+(?:\.\d+)?$/.test(raw))throw new HttpError(400,`${label} invalide.`);const n=Number(raw);if(!Number.isFinite(n)||n<0)throw new HttpError(400,`${label} ne peut pas être négatif.`);return n.toFixed(scale)};
const stockThreshold=(v:unknown)=>{const value=nonNegative(v,'Seuil minimum');if(Number(value)>99999999999.999)throw new HttpError(400,'Seuil minimum hors limites.');return value};
const categoryCode=(v:unknown)=>{const value=String(v??'').trim().toUpperCase().replace(/[\s-]+/g,'_');if(!/^[A-Z0-9_]{1,50}$/.test(value))throw new HttpError(400,'Code catégorie invalide.');return value};
const optionalId=(v:unknown)=>v==null||v===''?null:id(v);
const pagination=(q:Input)=>{const page=Math.max(1,Math.min(100000,Number(q.page)||1)),pageSize=Math.max(1,Math.min(100,Number(q.pageSize)||20));return{page,pageSize,offset:(page-1)*pageSize}};
const reportPeriod=(q:Input)=>{const now=new Date(),defaultFrom=`${now.getUTCFullYear()}-01-01`,defaultTo=`${now.getUTCFullYear()}-12-31`,from=q.from==null?defaultFrom:date(q.from,'Date de début'),to=q.to==null?defaultTo:date(q.to,'Date de fin');if(from>to)throw new HttpError(400,'Période invalide.');return{from,to}};
const andPredicates=(...values:{sql:string;params:any[]}[])=>({sql:values.map(x=>`(${x.sql})`).join(' AND '),params:values.flatMap(x=>x.params)});
const scopeFor=async(r:Request,permission:string)=>r.rbac?.isSuperAdmin?'GLOBAL':await assertPermission(r,permission);
function agencyPredicate(r:Request,scope:PermissionScope|null,agencyAlias='a',userAlias?:string){
  if(scope==='GLOBAL')return{sql:'1=1',params:[]as any[]};
  if(scope==='CONCESSION')return{sql:`${agencyAlias}.concession_id=(SELECT concession_id FROM agencies WHERE id=?)`,params:[r.user!.agencyId]};
  if(scope==='AGENCY')return{sql:`${agencyAlias}.id=?`,params:[r.user!.agencyId]};
  if(scope==='OWN'&&userAlias)return{sql:`${userAlias}.id=?`,params:[r.user!.sub]};
  throw new HttpError(403,'Le scope OWN ne s’applique pas à cette opération collective.');
}
function budgetPredicate(r:Request,scope:PermissionScope|null){
  if(scope==='GLOBAL')return{sql:'1=1',params:[]as any[]};
  if(scope==='CONCESSION')return{sql:'COALESCE(b.concession_id,ba.concession_id)=(SELECT concession_id FROM agencies WHERE id=?)',params:[r.user!.agencyId]};
  if(scope==='AGENCY')return{sql:'b.scope_type=\'agency\' AND b.agency_id=?',params:[r.user!.agencyId]};
  throw new HttpError(403,'Le scope OWN ne s’applique pas aux budgets.');
}
async function audit(c:PoolConnection,r:Request,type:string,entityId:string,action:string,value:unknown){await c.execute(`INSERT INTO audit_logs(user_id,module,entity_type,entity_id,action,new_values,ip_address,user_agent) VALUES(?,'hr',?,?,?,?,?,?)`,[r.user!.sub,type,entityId,action,JSON.stringify(value),r.ip??null,r.get('user-agent')??null])}
async function assertAgencyTarget(r:Request,permission:string,agencyId:string){const scope=await scopeFor(r,permission);const p=agencyPredicate(r,scope,'a');const rows=await query<RowDataPacket[]>(`SELECT a.id FROM agencies a WHERE a.id=? AND a.is_active=TRUE AND ${p.sql}`,[agencyId,...p.params]);if(!rows[0])throw new HttpError(403,'Agence hors périmètre.');return rows[0]}
async function activeActorAgency(r:Request){if(!r.user!.agencyId)throw new HttpError(403,'Aucune agence n’est associée à votre compte.');const[row]=await query<RowDataPacket[]>('SELECT id,concession_id,name FROM agencies WHERE id=? AND is_active=TRUE',[r.user!.agencyId]);if(!row)throw new HttpError(403,'Votre agence de rattachement est inactive ou introuvable.');return row}
async function actorConcession(r:Request){const[rows]=await query<RowDataPacket[]>('SELECT concession_id FROM agencies WHERE id=?',[r.user!.agencyId]);if(!rows)throw new HttpError(403,'Agence de rattachement invalide.');return String(rows.concession_id)}
async function categoryManagementConcession(r:Request,requested?:unknown){const scope=await scopeFor(r,'hr.stock.manage');if(scope==='OWN'||scope==='AGENCY')throw new HttpError(403,'La gestion des catégories exige un scope CONCESSION ou GLOBAL.');if(scope==='CONCESSION'){const concessionId=await actorConcession(r);if(requested!=null&&requested!==''&&id(requested)!==concessionId)throw new HttpError(403,'Concession hors périmètre.');return concessionId}return id(requested)}
async function budgetCategoryConcession(r:Request,permission:string,requested?:unknown,administration=false){const scope=await scopeFor(r,permission);if(scope==='OWN'||administration&&scope==='AGENCY')throw new HttpError(403,administration?'L’administration des catégories exige un scope CONCESSION ou GLOBAL.':'Le scope OWN ne s’applique pas aux catégories budgétaires.');if(scope==='GLOBAL')return requested==null||requested===''?null:id(requested);const actor=await activeActorAgency(r),concessionId=String(actor.concession_id);if(requested!=null&&requested!==''&&id(requested)!==concessionId)throw new HttpError(403,'Concession hors périmètre.');return concessionId}
async function lockedBudgetCategory(c:PoolConnection,categoryId:string,concessionId:string,activeOnly=true){const[rows]=await c.execute<RowDataPacket[]>(`SELECT id,concession_id,code,name,is_active FROM budget_categories WHERE id=? AND concession_id=?${activeOnly?' AND is_active=TRUE':''} FOR UPDATE`,[categoryId,concessionId]);if(!rows[0])throw new HttpError(400,activeOnly?'Catégorie budgétaire active introuvable dans cette concession.':'Catégorie budgétaire introuvable dans cette concession.');return rows[0]}
async function employee(r:Request,permission:string,employeeId:string,lock?:PoolConnection){const scope=await scopeFor(r,permission),p=agencyPredicate(r,scope,'a','u'),sql=`SELECT ep.*,u.agency_id,a.concession_id FROM employee_profiles ep JOIN users u ON u.id=ep.user_id JOIN agencies a ON a.id=u.agency_id WHERE ep.id=? AND ${p.sql}${lock?' FOR UPDATE':''}`;const rows=lock?(await lock.execute<RowDataPacket[]>(sql,[employeeId,...p.params]))[0]:await query<RowDataPacket[]>(sql,[employeeId,...p.params]);if(!rows[0])throw new HttpError(404,'Employé introuvable dans votre périmètre.');return rows[0]}
async function stockItem(r:Request,permission:string,itemId:string,c?:PoolConnection,activeOnly=false){const scope=await scopeFor(r,permission),p=agencyPredicate(r,scope,'a'),sql=`SELECT i.* FROM internal_stock_items i JOIN agencies a ON a.id=i.agency_id WHERE i.id=?${activeOnly?' AND i.is_active=TRUE':''} AND ${p.sql}${c?' FOR UPDATE':''}`;const rows=c?(await c.execute<RowDataPacket[]>(sql,[itemId,...p.params]))[0]:await query<RowDataPacket[]>(sql,[itemId,...p.params]);if(!rows[0])throw new HttpError(404,activeOnly?'Article actif introuvable dans votre périmètre.':'Article introuvable dans votre périmètre.');return rows[0]}
async function budget(r:Request,permission:string,budgetId:string,c?:PoolConnection){const scope=await scopeFor(r,permission),p=budgetPredicate(r,scope),sql=`SELECT b.*,COALESCE(b.concession_id,ba.concession_id) target_concession_id FROM budgets b LEFT JOIN agencies ba ON ba.id=b.agency_id WHERE b.id=? AND ${p.sql}${c?' FOR UPDATE':''}`;const rows=c?(await c.execute<RowDataPacket[]>(sql,[budgetId,...p.params]))[0]:await query<RowDataPacket[]>(sql,[budgetId,...p.params]);if(!rows[0])throw new HttpError(404,'Budget introuvable dans votre périmètre.');return rows[0]}

hrRouter.get('/hr/employees',requirePermission('hr.employees.view'),asyncHandler(async(r,res)=>{
  const scope=await scopeFor(r,'hr.employees.view'),p=agencyPredicate(r,scope,'a','u'),{page,pageSize,offset}=pagination(r.query),params=[...p.params] as any[];let where=p.sql;
  if(r.query.status){const s=String(r.query.status);if(!['active','inactive','departed'].includes(s))throw new HttpError(400,'Statut invalide.');where+=' AND ep.employment_status=?';params.push(s)}
  if(r.query.agencyId){await assertAgencyTarget(r,'hr.employees.view',id(r.query.agencyId));where+=' AND u.agency_id=?';params.push(r.query.agencyId)}
  if(r.query.search){const q=`%${String(r.query.search).trim().slice(0,120)}%`;where+=' AND (CONCAT_WS(\' \',u.first_name,u.last_name) LIKE ? OR ep.employee_number LIKE ? OR ep.position_title LIKE ?)';params.push(q,q,q)}
  const context=await rbac(r),salaryAllowed=can(context,'hr.salary.view'),salaryScope=context.isSuperAdmin?'GLOBAL':context.permissions.get('hr.salary.view'),salaryVisibility=salaryAllowed?agencyPredicate(r,salaryScope??null,'a','u'):null;
  const salarySelection=salaryVisibility?`, CASE WHEN ${salaryVisibility.sql} THEN (SELECT sh.amount FROM salary_history sh WHERE sh.employee_profile_id=ep.id AND sh.effective_date<=CURDATE() ORDER BY sh.effective_date DESC,sh.id DESC LIMIT 1) ELSE NULL END current_salary`:'';
  const [countRows,rows]=await Promise.all([query<RowDataPacket[]>(`SELECT COUNT(*) total FROM employee_profiles ep JOIN users u ON u.id=ep.user_id JOIN agencies a ON a.id=u.agency_id WHERE ${where}`,params),query<RowDataPacket[]>(`SELECT ep.id,ep.employee_number,ep.position_title,ep.hire_date,ep.employment_status,ep.created_at,ep.updated_at,u.id user_id,u.first_name,u.last_name,u.email,u.phone,u.is_active account_active,a.id agency_id,a.name agency_name${salarySelection} FROM employee_profiles ep JOIN users u ON u.id=ep.user_id JOIN agencies a ON a.id=u.agency_id WHERE ${where} ORDER BY u.last_name,u.first_name LIMIT ? OFFSET ?`,[...(salaryVisibility?.params??[]),...params,pageSize,offset])]);
  res.json({items:rows.map(x=>({...x,id:String(x.id),user_id:String(x.user_id),agency_id:String(x.agency_id),current_salary:salaryAllowed&&x.current_salary!=null?Number(x.current_salary):undefined})),total:Number(countRows[0]?.total??0),page,pageSize});
}));

hrRouter.patch('/hr/employees/:id',requirePermission('hr.employees.manage'),asyncHandler(async(r,res)=>{
  const employeeId=id(r.params.id),body=r.body as Input,status=body.status==null?null:String(body.status);if(status&&!['active','inactive','departed'].includes(status))throw new HttpError(400,'Statut RH invalide.');
  await transaction(async c=>{const current=await employee(r,'hr.employees.manage',employeeId,c),sets:string[]=[],values:any[]=[];if(Object.hasOwn(body,'employeeNumber')){sets.push('employee_number=?');values.push(text(body.employeeNumber,'Matricule',true,50))}if(Object.hasOwn(body,'positionTitle')){sets.push('position_title=?');values.push(text(body.positionTitle,'Fonction',false,120))}if(Object.hasOwn(body,'hireDate')){sets.push('hire_date=?');values.push(date(body.hireDate,'Date d’embauche'))}if(status){sets.push('employment_status=?');values.push(status)}if(!sets.length)throw new HttpError(400,'Aucune modification valide.');sets.push('updated_by=?');values.push(r.user!.sub);await c.execute(`UPDATE employee_profiles SET ${sets.join(',')} WHERE id=?`,[...values,employeeId]);await audit(c,r,'employee',employeeId,'employee.updated',{before:{status:current.employment_status},status})});
  res.json({success:true});
}));

hrRouter.get('/hr/employees/:id/salaries',requirePermission('hr.salary.view'),asyncHandler(async(r,res)=>{const employeeId=id(r.params.id);await employee(r,'hr.salary.view',employeeId);const rows=await query<RowDataPacket[]>(`SELECT sh.id,sh.amount,sh.effective_date,sh.created_at,CONCAT_WS(' ',u.first_name,u.last_name) author_name FROM salary_history sh LEFT JOIN users u ON u.id=sh.created_by WHERE sh.employee_profile_id=? ORDER BY sh.effective_date DESC,sh.id DESC`,[employeeId]);res.json(rows.map(x=>({...x,id:String(x.id),amount:Number(x.amount)})))}));
hrRouter.post('/hr/employees/:id/salaries',requirePermission('hr.salary.manage'),asyncHandler(async(r,res)=>{const employeeId=id(r.params.id),amount=positive(r.body.amount,'Montant'),effectiveDate=date(r.body.effectiveDate,'Date d’effet');const salaryId=await transaction(async c=>{await employee(r,'hr.salary.manage',employeeId,c);try{const[result]=await c.execute<ResultSetHeader>('INSERT INTO salary_history(employee_profile_id,amount,effective_date,created_by) VALUES(?,?,?,?)',[employeeId,amount,effectiveDate,r.user!.sub]);await audit(c,r,'salary',String(result.insertId),'salary.created',{employeeId,amount,effectiveDate});return String(result.insertId)}catch(error:any){if(error?.code==='ER_DUP_ENTRY')throw new HttpError(409,'Un salaire existe déjà à cette date d’effet.');throw error}});res.status(201).json({id:salaryId,amount:Number(amount),effectiveDate})}));

hrRouter.get('/hr/stock-agencies',requirePermission('hr.stock.manage'),asyncHandler(async(r,res)=>{const scope=await scopeFor(r,'hr.stock.manage'),p=agencyPredicate(r,scope,'a'),rows=await query<RowDataPacket[]>(`SELECT a.id,a.name,a.code FROM agencies a WHERE a.is_active=TRUE AND ${p.sql} ORDER BY a.name`,p.params);res.json(rows.map(x=>({id:String(x.id),name:String(x.name),code:String(x.code)})))}));
hrRouter.get('/hr/stock-concessions',requirePermission('hr.stock.manage'),asyncHandler(async(r,res)=>{const scope=await scopeFor(r,'hr.stock.manage');if(scope==='OWN'||scope==='AGENCY')throw new HttpError(403,'La gestion des catégories exige un scope CONCESSION ou GLOBAL.');const rows=await query<RowDataPacket[]>(`SELECT c.id,c.name FROM concessions c WHERE c.is_active=TRUE${scope==='CONCESSION'?' AND c.id=(SELECT concession_id FROM agencies WHERE id=?)':''} ORDER BY c.name,c.id`,scope==='CONCESSION'?[r.user!.agencyId]:[]);res.json(rows.map(x=>({id:String(x.id),name:String(x.name)})))}));
hrRouter.get('/hr/internal-stock-categories',asyncHandler(async(r,res)=>{const context=await rbac(r),permission=can(context,'hr.stock.manage')?'hr.stock.manage':'hr.stock.view',scope=await scopeFor(r,permission);if(scope==='OWN')throw new HttpError(403,'Le scope OWN ne permet pas de consulter ce référentiel collectif.');const params:unknown[]=[];let where='1=1';if(scope!=='GLOBAL'){where='c.concession_id=(SELECT concession_id FROM agencies WHERE id=?)';params.push(r.user!.agencyId)}if(r.query.active==='true')where+=' AND c.is_active=TRUE';const rows=await query<RowDataPacket[]>(`SELECT c.id,c.concession_id,concession.name concession_name,c.code,c.name,c.is_active,c.created_at,c.updated_at FROM internal_stock_categories c JOIN concessions concession ON concession.id=c.concession_id WHERE ${where} ORDER BY c.name,c.id`,params);res.json(rows.map(x=>({...x,id:String(x.id),concession_id:String(x.concession_id),concession_name:String(x.concession_name),is_active:Boolean(x.is_active)})))}));
hrRouter.post('/hr/internal-stock-categories',requirePermission('hr.stock.manage'),asyncHandler(async(r,res)=>{const b=r.body as Input,concessionId=await categoryManagementConcession(r,b.concessionId),name=text(b.name,'Nom catégorie',true,100)!,code=categoryCode(b.code);const categoryId=await transaction(async c=>{try{const[result]=await c.execute<ResultSetHeader>('INSERT INTO internal_stock_categories(concession_id,code,name,is_active) SELECT ?,?,?,TRUE FROM concessions WHERE id=? AND is_active=TRUE',[concessionId,code,name,concessionId]);if(!result.affectedRows)throw new HttpError(400,'Concession inexistante ou inactive.');await audit(c,r,'internal_stock_category',String(result.insertId),'stock.category.created',{concessionId,code,name});return String(result.insertId)}catch(error:any){if(error?.code==='ER_DUP_ENTRY')throw new HttpError(409,'Ce code catégorie existe déjà dans cette concession.');throw error}});res.status(201).json({id:categoryId})}));
hrRouter.patch('/hr/internal-stock-categories/:id',requirePermission('hr.stock.manage'),asyncHandler(async(r,res)=>{const categoryId=id(r.params.id),scope=await scopeFor(r,'hr.stock.manage');if(scope==='OWN'||scope==='AGENCY')throw new HttpError(403,'La gestion des catégories exige un scope CONCESSION ou GLOBAL.');const concessionId=scope==='CONCESSION'?await actorConcession(r):null,b=r.body as Input,name=text(b.name,'Nom catégorie',true,100)!,code=categoryCode(b.code);if(typeof b.isActive!=='boolean')throw new HttpError(400,'Statut catégorie invalide.');const isActive=b.isActive;await transaction(async c=>{const[rows]=await c.execute<RowDataPacket[]>(`SELECT id,concession_id,code,name,is_active FROM internal_stock_categories WHERE id=?${concessionId?' AND concession_id=?':''} FOR UPDATE`,[categoryId,...(concessionId?[concessionId]:[])]),current=rows[0];if(!current)throw new HttpError(404,'Catégorie introuvable dans votre périmètre.');try{await c.execute('UPDATE internal_stock_categories SET code=?,name=?,is_active=? WHERE id=?',[code,name,isActive,categoryId])}catch(error:any){if(error?.code==='ER_DUP_ENTRY')throw new HttpError(409,'Ce code catégorie existe déjà dans cette concession.');throw error}await audit(c,r,'internal_stock_category',categoryId,'stock.category.updated',{before:{code:current.code,name:current.name,isActive:Boolean(current.is_active)},after:{code,name,isActive}})});res.json({success:true})}));
hrRouter.get('/hr/internal-stock',requirePermission('hr.stock.view'),asyncHandler(async(r,res)=>{const scope=await scopeFor(r,'hr.stock.view'),p=agencyPredicate(r,scope,'a'),params=[...p.params] as unknown[];let where=p.sql;if(r.query.includeInactive!=='true')where+=' AND i.is_active=TRUE';if(r.query.agencyId){await assertAgencyTarget(r,'hr.stock.view',id(r.query.agencyId));where+=' AND i.agency_id=?';params.push(r.query.agencyId)}if(r.query.search){where+=' AND CONCAT_WS(\' \',i.designation,i.reference,c.name,i.category) LIKE ?';params.push(`%${String(r.query.search).trim().slice(0,120)}%`)}const rows=await query<RowDataPacket[]>(`SELECT i.*,COALESCE(c.name,i.category) category,c.code category_code,a.name agency_name,(i.current_quantity<=i.minimum_quantity) below_minimum FROM internal_stock_items i JOIN agencies a ON a.id=i.agency_id LEFT JOIN internal_stock_categories c ON c.id=i.category_id WHERE ${where} ORDER BY i.designation`,params);res.json(rows.map(x=>({...x,id:String(x.id),agency_id:String(x.agency_id),category_id:x.category_id==null?null:String(x.category_id),current_quantity:Number(x.current_quantity),minimum_quantity:Number(x.minimum_quantity),below_minimum:Number(x.below_minimum)===1,is_active:Boolean(x.is_active)})))}));
hrRouter.post('/hr/internal-stock',requirePermission('hr.stock.manage'),asyncHandler(async(r,res)=>{const b=r.body as Input,agencyId=id(b.agencyId),categoryId=id(b.categoryId);await assertAgencyTarget(r,'hr.stock.manage',agencyId);const designation=text(b.designation,'Désignation',true)!,unit=text(b.unit,'Unité',true,40)!,minimum=stockThreshold(b.minimumQuantity??0);const itemId=await transaction(async c=>{const[categories]=await c.execute<RowDataPacket[]>('SELECT c.id,c.name FROM internal_stock_categories c JOIN agencies a ON a.concession_id=c.concession_id WHERE c.id=? AND c.is_active=TRUE AND a.id=? FOR UPDATE',[categoryId,agencyId]),category=categories[0];if(!category)throw new HttpError(400,'Catégorie inactive, inexistante ou étrangère à la concession de l’agence.');const[result]=await c.execute<ResultSetHeader>('INSERT INTO internal_stock_items(agency_id,designation,reference,category,category_id,unit,minimum_quantity,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?)',[agencyId,designation,text(b.reference,'Référence',false,100),category.name,categoryId,unit,minimum,r.user!.sub,r.user!.sub]);await audit(c,r,'internal_stock_item',String(result.insertId),'stock.item.created',{agencyId,categoryId,designation});return String(result.insertId)});res.status(201).json({id:itemId})}));
hrRouter.patch('/hr/internal-stock/:id/minimum-threshold',requirePermission('hr.stock.manage'),asyncHandler(async(r,res)=>{const itemId=id(r.params.id),minimum=stockThreshold(r.body.minimumQuantity);await transaction(async c=>{const current=await stockItem(r,'hr.stock.manage',itemId,c,true);await c.execute('UPDATE internal_stock_items SET minimum_quantity=?,updated_by=? WHERE id=?',[minimum,r.user!.sub,itemId]);await audit(c,r,'internal_stock_item',itemId,'stock.item.minimum.updated',{before:{minimumQuantity:Number(current.minimum_quantity)},after:{minimumQuantity:Number(minimum)}})});res.json({success:true,minimumQuantity:Number(minimum)})}));
hrRouter.patch('/hr/internal-stock/:id/status',requirePermission('hr.stock.manage'),asyncHandler(async(r,res)=>{const itemId=id(r.params.id),value=r.body.isActive;if(typeof value!=='boolean')throw new HttpError(400,'Statut article invalide.');await transaction(async c=>{const current=await stockItem(r,'hr.stock.manage',itemId,c);await c.execute('UPDATE internal_stock_items SET is_active=?,updated_by=? WHERE id=?',[value,r.user!.sub,itemId]);await audit(c,r,'internal_stock_item',itemId,'stock.item.status.updated',{before:{isActive:Boolean(current.is_active)},after:{isActive:value}})});res.json({success:true,isActive:value})}));
hrRouter.get('/hr/internal-stock/:id/movements',requirePermission('hr.stock.view'),asyncHandler(async(r,res)=>{const itemId=id(r.params.id);await stockItem(r,'hr.stock.view',itemId);const rows=await query<RowDataPacket[]>(`SELECT m.*,CONCAT_WS(' ',u.first_name,u.last_name) author_name FROM internal_stock_movements m LEFT JOIN users u ON u.id=m.performed_by WHERE m.item_id=? ORDER BY m.movement_date DESC,m.id DESC`,[itemId]);res.json(rows.map(x=>({...x,id:String(x.id),item_id:String(x.item_id),agency_id:String(x.agency_id),quantity:Number(x.quantity),quantity_before:Number(x.quantity_before),quantity_after:Number(x.quantity_after)})))}));
